using System;using System.Windows.Input;
namespace Dafeiyu.Tests {public static class ShortcutCaptureTests {public static int Main(){try{int checks=0;Action<bool,string> check=(ok,m)=>{if(!ok)throw new Exception(m);checks++;};
check(ShortcutCapture.Format(Key.N,ModifierKeys.Control)=="Ctrl+N","actual CtrlN");check(ShortcutCapture.Format(Key.F12,ModifierKeys.Alt|ModifierKeys.Control|ModifierKeys.Shift)=="Ctrl+Alt+Shift+F12","canonical modifier order");check(ShortcutCapture.Format(Key.D1,ModifierKeys.Control)=="Ctrl+D1","top row digits");check(ShortcutCapture.Format(Key.OemComma,ModifierKeys.Control)=="Ctrl+OemComma","OEM physical key");check(ShortcutCapture.Format(Key.LeftCtrl,ModifierKeys.Control)==null,"modifier alone ignored");check(ShortcutCapture.Format(Key.ImeProcessed,ModifierKeys.Control)==null,"IME composition ignored");check(ShortcutCapture.Format(Key.A,ModifierKeys.None)==null,"plain text not accepted");var s=new PetSettings();string error;check(!ShortcutCatalog.Validate(s,"newchat","Ctrl+C",out error),"editing keys remain reserved");Console.WriteLine("PASS: "+checks+" key capture checks");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}}}
